package com.citacloud.springboot.contacloud.app.models;
import jakarta.persistence.*;import java.time.OffsetDateTime;import java.util.UUID;
@Entity @Table(name="warehouse") public class Almacen{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false)private UUID empresaId;@Column(name="code",nullable=false,length=30)private String codigo;@Column(name="name",nullable=false,length=120)private String nombre;@Column(name="active",nullable=false)private boolean activo;@Column(name="created_at",nullable=false,insertable=false,updatable=false)private OffsetDateTime creadoEn;@Column(name="created_by")private UUID creadoPor;protected Almacen(){}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getEmpresaId(){return empresaId;}public String getCodigo(){return codigo;}public String getNombre(){return nombre;}public boolean isActivo(){return activo;}}
